func lsPushNum(et *port.Cells, v int32) int32 {
	// The decimal digits of a non-negative number, appended to `et`.
	var d int32 = 1
	var x int32 = v
	for x >= 10 {
		d *= 10
		x = x / 10
	}
	x = v
	for d > 0 {
		port.CellsPush(et, 48+(x/d))
		x -= (x / d) * d
		d = d / 10
	}
	return 0
}

func LsWrapBegin(et *port.Cells, opener int32, code int32, value int32) int32 {
	// Start a new text run at the end of `et`: the group's opener, its header cell (`ls-s-base` + code), the
	// value's digits when it is not negative, and the separator. Answers the run's start; the caller then
	// pushes the marker's text, `ls-wrap-end`, and what follows, and `ls-wrap-set` points the word at the run.
	var s int32 = port.CellsLen(et)
	port.CellsPush(et, opener)
	port.CellsPush(et, LsSBase()+code)
	if value >= 0 {
		lsPushNum(et, value)
	}
	port.CellsPush(et, LsSSep())
	return s
}

func LsWrapEnd(et *port.Cells) int32 {
	port.CellsPush(et, LsSEnd())
	return 0
}

func LsWrapSet(wd *port.Cells, et *port.Cells, w int32, start int32) int32 {
	// Point word w at the run that begins at `start` and ends at the end of `et`.
	evidence.WdSet(wd, w, evidence.HdTstart(), start)
	evidence.WdSet(wd, w, evidence.HdTlen(), port.CellsLen(et)-start)
	return 0
}

func LsCopyWord(et *port.Cells, wd *port.Cells, w int32, from int32) int32 {
	// Append the code points of word w's current text from index `from` to `et`.
	var ts int32 = evidence.WdGet(wd, w, evidence.HdTstart())
	var tl int32 = evidence.WdGet(wd, w, evidence.HdTlen())
	var j int32 = from
	for j < tl {
		port.CellsPush(et, port.CellsAt(et, ts+j))
		j += 1
	}
	return 0
}

func lsWrapItem(wd *port.Cells, et *port.Cells, w int32, scheme int32, value int32, mlen int32, bullet int32) int32 {
	// Make word w start with an item group. A TEXT marker (`bullet` -1): the group holds the word's first `mlen`
	// code points. A SHAPE (`bullet` the character the shape is): the group holds that character and the word is
	// kept whole after it.
	var s int32 = LsWrapBegin(et, LsSItem(), scheme, value)
	if bullet < 0 {
		var j int32 = 0
		var ts int32 = evidence.WdGet(wd, w, evidence.HdTstart())
		for j < mlen {
			port.CellsPush(et, port.CellsAt(et, ts+j))
			j += 1
		}
		LsWrapEnd(et)
		LsCopyWord(et, wd, w, mlen)
	} else {
		port.CellsPush(et, bullet)
		LsWrapEnd(et)
		LsCopyWord(et, wd, w, 0)
	}
	LsWrapSet(wd, et, w, s)
	return 0
}

func LsUpright(ln *port.Cells, l int32) bool {
	var r int32 = evidence.LnGet(ln, l, evidence.LhRot())
	return (r < 100) || (r > 35900)
}

func LsLineSize(sf *port.Cells, ln *port.Cells, l int32) int32 {
	// The size the line's text is set in (centipoints): the style inventory's, else its height over 5/4.
	var s int32 = style.StGet(sf, l, style.SfkSize())
	if s > 0 {
		return LsCap(s)
	}
	return LsCap((LsCap(evidence.LnGet(ln, l, evidence.LhY1())-evidence.LnGet(ln, l, evidence.LhY0())) * 4) / 5)
}

func lsPages(ln *port.Cells, pi *port.Cells) int32 {
	// `pi`: for page p (1-based) the first line of the page plus one and one past its last, cells 2p and 2p+1; the
	// lines of a page are consecutive in `ln` (the text layer writes them page by page). Answers 1, or 0 when they
	// are not (a stage that reordered the lines): then no shape is associated.
	var n int32 = evidence.LnCount(ln)
	var l int32 = 0
	var last int32 = 0
	var mx int32 = 0
	port.CellsDrop(pi, 0)
	for l < n {
		var p int32 = evidence.LnGet(ln, l, evidence.LhPage())
		if p < last {
			return 0
		}
		if p > 100000 {
			return 0
		}
		last = p
		if p > mx {
			mx = p
		}
		l += 1
	}
	l = 0
	for l < (2 * (mx + 2)) {
		port.CellsPush(pi, 0)
		l += 1
	}
	l = 0
	for l < n {
		var p int32 = evidence.LnGet(ln, l, evidence.LhPage())
		if port.CellsAt(pi, 2*p) == 0 {
			port.CellsSet(pi, 2*p, l+1)
		}
		port.CellsSet(pi, (2*p)+1, l+1)
		l += 1
	}
	return 1
}

func lsAttach(ln *port.Cells, sf *port.Cells, hc *port.Cells, l int32, r int32, x1 int32, w int32, cy0 int32) int32 {
	// Associate shape r (its right edge x1, its width w, its centre cy) with line l if the shape stands where a
	// bullet stands: a fraction of an em to the left of the first word, on the x-height, of a fraction of an em in
	// size. The line keeps the nearest one. Answers 1 when this was the first shape the line got.
	var cy int32 = LsCap(cy0)
	var sz int32 = LsLineSize(sf, ln, l)
	var lx int32 = LsCap(evidence.LnGet(ln, l, evidence.LhX0()))
	var by int32 = LsCap(evidence.LnGet(ln, l, evidence.LhBy0()))
	var gap int32 = LsCap(lx - LsCap(x1))
	if ((gap * 16) >= sz) && ((gap * 10) <= (sz * 25)) && ((w * 100) >= (sz * 12)) && ((w * 100) <= (sz * 70)) && ((cy * 100) >= ((by * 100) - (sz * 80))) && ((cy * 10) <= ((by * 10) - sz)) {
		var old int32 = LsGet(hc, l, LsKShape())
		if (old == 0) || (gap < LsGet(hc, l, LsKGap())) {
			LsPut(hc, l, LsKShape(), r+1)
			LsPut(hc, l, LsKGap(), gap)
			if old == 0 {
				return 1
			}
		}
	}
	return 0
}

func lsShapes(ln *port.Cells, sf *port.Cells, pa *port.Cells, pi *port.Cells, hc *port.Cells) int32 {
	// Associate every small filled or stroked circle or square with the line it precedes (see the module's head):
	// the line's row gets 1 + the path's row and the gap. Answers how many lines got one.
	var np int32 = evidence.PaCount(pa)
	var r int32 = 0
	var got int32 = 0
	var seen int32 = 0
	var l int32 = 0
	for (r < np) && (seen < lsMaxshape) {
		var fl int32 = evidence.PaGet(pa, r, evidence.PfFlags())
		var x0 int32 = evidence.PaGet(pa, r, evidence.PfX0())
		var y0 int32 = evidence.PaGet(pa, r, evidence.PfY0())
		var x1 int32 = evidence.PaGet(pa, r, evidence.PfX1())
		var y1 int32 = evidence.PaGet(pa, r, evidence.PfY1())
		var w int32 = x1 - x0
		var h int32 = y1 - y0
		var p int32 = evidence.PaGet(pa, r, evidence.PfPage())
		if ((fl & 4) == 0) && ((fl & 24) != 0) && (w > 0) && (h > 0) && (w < 1500) && (h < 1500) && (p >= 1) && (((2 * p) + 1) < port.CellsLen(pi)) && ((4 * LsAbs(w-h)) <= LsMax(w, h)) {
			seen += 1
			l = port.CellsAt(pi, 2*p) - 1
			for (l >= 0) && (l < port.CellsAt(pi, (2*p)+1)) {
				if LsUpright(ln, l) {
					got += lsAttach(ln, sf, hc, l, r, x1, w, (y0+y1)/2)
				}
				l += 1
			}
		}
		r += 1
	}
	return got
}

func lsShapeChar(pa *port.Cells, r int32) int32 {
	// The bullet a path stands for: a filled disc, a ring, a filled square, a hollow square.
	var fl int32 = evidence.PaGet(pa, r, evidence.PfFlags())
	var k int32 = evidence.PaGet(pa, r, evidence.PfKind())
	var filled int32 = fl & 8
	if k == evidence.PaCurve() {
		if filled != 0 {
			return 8226
		}
		return 9702
	}
	if filled != 0 {
		return 9642
	}
	return 9643
}

func LsFirstWord(wd *port.Cells, ln *port.Cells, l int32) int32 {
	// The first word of the line that has text; -1 when none.
	var w0 int32 = evidence.LnGet(ln, l, evidence.LhFirst())
	var wn int32 = evidence.LnGet(ln, l, evidence.LhCount())
	var i int32 = 0
	for i < wn {
		if LsWl(wd, w0+i) > 0 {
			return w0 + i
		}
		i += 1
	}
	return -1
}

func LsSecondWord(wd *port.Cells, ln *port.Cells, l int32) int32 {
	var w0 int32 = evidence.LnGet(ln, l, evidence.LhFirst())
	var wn int32 = evidence.LnGet(ln, l, evidence.LhCount())
	var i int32 = 0
	var seen int32 = 0
	for i < wn {
		if LsWl(wd, w0+i) > 0 {
			if seen == 1 {
				return w0 + i
			}
			seen += 1
		}
		i += 1
	}
	return -1
}

func lsPushCand(cd *port.Cells, ln *port.Cells, l int32, sch int32, val int32, sch2 int32, val2 int32, pun int32, cls int32, ch int32, x int32) int32 {
	// Append one candidate row of `LS_CD` cells: line, page, scheme, value, scheme2, value2, punct, x0 of the line,
	// class (1 strong bullet, 2 weak, 3 number or letter, 4 shape), the bullet character.
	port.CellsPush(cd, l)
	port.CellsPush(cd, evidence.LnGet(ln, l, evidence.LhPage()))
	port.CellsPush(cd, sch)
	port.CellsPush(cd, val)
	port.CellsPush(cd, sch2)
	port.CellsPush(cd, val2)
	port.CellsPush(cd, pun)
	port.CellsPush(cd, x)
	port.CellsPush(cd, cls)
	port.CellsPush(cd, ch)
	return 0
}

func lsMlen(wd *port.Cells, et *port.Cells, w int32, ws *port.Cells) int32 {
	// The marker length of word w (the parser's cell 4).
	LsParse(wd, et, w, ws)
	return port.CellsAt(ws, 4)
}

func lsTextx(wd *port.Cells, ln *port.Cells, et *port.Cells, l int32, w int32, cls int32, ws *port.Cells) int32 {
	// The x where the item's text starts: the word after the marker; a glued marker's share of its word; the
	// word itself for a shape. 0 when the line has nothing after the marker. (Markers are often right aligned, so
	// the marker's own x says little about the indent: the text's does.)
	if cls == 4 {
		return evidence.WdGet(wd, w, evidence.HdX0())
	}
	var w2 int32 = LsSecondWord(wd, ln, l)
	var wl int32 = LsWl(wd, w)
	var ml int32 = lsMlen(wd, et, w, ws)
	if ml < wl {
		return evidence.WdGet(wd, w, evidence.HdX0()) + (((evidence.WdGet(wd, w, evidence.HdX1()) - evidence.WdGet(wd, w, evidence.HdX0())) * ml) / wl)
	}
	if w2 >= 0 {
		return evidence.WdGet(wd, w2, evidence.HdX0())
	}
	return 0
}

func lsCollect(wd *port.Cells, ln *port.Cells, et *port.Cells, hc *port.Cells, cd *port.Cells, ws *port.Cells) int32 {
	// One candidate row per line that starts with a marker, or with a bullet shape, in line order. Lines that are
	// headings, not upright, or already taken (a note, a caption) are left out; a line whose only word is the
	// marker has no item text and is left out.
	var n int32 = evidence.LnCount(ln)
	var l int32 = 0
	var c int32 = 0
	var w int32 = 0
	var tx int32 = 0
	var cls int32 = 0
	port.CellsDrop(cd, 0)
	for (l < n) && (c < lsMaxcand) {
		if LsUpright(ln, l) && (heading.HdLevel(hc, l) == 0) && (LsGet(hc, l, LsKFlags()) == 0) {
			w = LsFirstWord(wd, ln, l)
			if w >= 0 {
				cls = LsParse(wd, et, w, ws)
				if (cls > 0) && ((port.CellsAt(ws, 4) < LsWl(wd, w)) || (LsSecondWord(wd, ln, l) >= 0)) {
					tx = lsTextx(wd, ln, et, l, w, cls, ws)
					LsParse(wd, et, w, ws)
					lsPushCand(cd, ln, l, port.CellsAt(ws, 0), port.CellsAt(ws, 1), port.CellsAt(ws, 2), port.CellsAt(ws, 3), port.CellsAt(ws, 5), cls, port.CellsAt(ws, 6), tx)
					c += 1
				}
				if (cls == 0) && (LsGet(hc, l, LsKShape()) > 0) {
					tx = lsTextx(wd, ln, et, l, w, 4, ws)
					lsPushCand(cd, ln, l, LsScBullet(), 0, 0, 0, 0, 4, 0, tx)
					c += 1
				}
			}
		}
		l += 1
	}
	return c
}

func lsCget(cd *port.Cells, i int32, f int32) int32 {
	return port.CellsAt(cd, (i*lsCd)+f)
}

func lsCloseVal(s int32, v int32, t int32, u int32) int32 {
	// 1 when two readings are of one scheme and their values differ by one to LS_NEAR.
	if (s == 0) || (s != t) {
		return 0
	}
	var d int32 = LsAbs(v - u)
	if (d >= 1) && (d <= lsNear) {
		return 1
	}
	return 0
}

func lsConfirm(cd *port.Cells, nc int32, i int32) int32 {
	// Is candidate i corroborated by another near it: for a bullet, one of the same kind at the same indent on the
	// same or an adjacent page; for a number or a letter, one of the same scheme and punctuation at the same indent
	// whose value differs by one (or by a few: a list that skips). Answers the reading that is confirmed, 1 (the
	// candidate's first) or 2 (its second), 0 none.
	var cls int32 = lsCget(cd, i, 8)
	var pg int32 = lsCget(cd, i, 1)
	var x int32 = lsCget(cd, i, 7)
	var j int32 = LsMax(0, i-lsWin)
	var c1 int32 = 0
	var c2 int32 = 0
	for (j < nc) && (j <= (i + lsWin)) {
		if (j != i) && (LsAbs(lsCget(cd, j, 1)-pg) <= 1) && (LsAbs(lsCget(cd, j, 7)-x) <= lsXtol) && (lsCget(cd, j, 6) == lsCget(cd, i, 6)) {
			if (cls == 1) || ((cls == 2) || (cls == 4)) {
				if cls == lsCget(cd, j, 8) {
					if (cls == 4) || (lsCget(cd, j, 9) == lsCget(cd, i, 9)) {
						c1 = 1
					}
				}
			} else {
				if (1 == lsCloseVal(lsCget(cd, i, 2), lsCget(cd, i, 3), lsCget(cd, j, 2), lsCget(cd, j, 3))) || (1 == lsCloseVal(lsCget(cd, i, 2), lsCget(cd, i, 3), lsCget(cd, j, 4), lsCget(cd, j, 5))) {
					c1 = 1
				}
				if (1 == lsCloseVal(lsCget(cd, i, 4), lsCget(cd, i, 5), lsCget(cd, j, 2), lsCget(cd, j, 3))) || (1 == lsCloseVal(lsCget(cd, i, 4), lsCget(cd, i, 5), lsCget(cd, j, 4), lsCget(cd, j, 5))) {
					c2 = 1
				}
			}
		}
		j += 1
	}
	if c1 == 1 {
		return 1
	}
	if c2 == 1 {
		return 2
	}
	return 0
}

func lsHangEvidence(ln *port.Cells, sf *port.Cells, hc *port.Cells, l int32, textx int32) int32 {
	// Does the line below l go on the item: not itself a marker line, starting at the item's text x, close below?
	var b int32 = style.StGet(sf, l, style.SfkBelow())
	if b < 0 {
		return 0
	}
	if !LsUpright(ln, b) {
		return 0
	}
	if LsGet(hc, b, LsKFlags()) != 0 {
		return 0
	}
	var sz int32 = LsLineSize(sf, ln, l)
	var g int32 = LsCap(style.StGet(sf, l, style.SfkGapBelow()))
	var bx int32 = LsCap(evidence.LnGet(ln, b, evidence.LhX0()))
	var mx int32 = LsCap(evidence.LnGet(ln, l, evidence.LhX0()))
	if (g * 10) > (sz * 15) {
		return 0
	}
	if (((bx - mx) * 100) >= (sz * 50)) && (LsAbs(bx-textx) <= (sz / 2)) {
		return 1
	}
	return 0
}

func lsWalk(ln *port.Cells, sf *port.Cells, hc *port.Cells) int32 {
	// Mark the lines that GO ON an item: from each item line down the page while the next line is not a start, is
	// upright, close below, and sits at the item's text x. The same x and slop as the item's.
	var n int32 = evidence.LnCount(ln)
	var l int32 = 0
	for l < n {
		if (LsGet(hc, l, LsKFlags()) & 1) == 1 {
			var tx int32 = LsGet(hc, l, LsKTextx())
			var tl int32 = LsGet(hc, l, LsKTol())
			var cur int32 = l
			var steps int32 = 0
			var more int32 = 1
			for (more == 1) && (steps < 200) {
				var b int32 = style.StGet(sf, cur, style.SfkBelow())
				more = 0
				if (b >= 0) && LsUpright(ln, b) {
					if (LsStart(hc, b) == 0) && ((LsGet(hc, b, LsKFlags()) & 2) == 0) && (style.StGet(sf, cur, style.SfkGapBelow()) <= (3 * tl)) && (evidence.LnGet(ln, b, evidence.LhX0()) >= (tx - tl)) && (evidence.LnGet(ln, b, evidence.LhX0()) <= (tx + tl)) {
						LsPut(hc, b, LsKFlags(), LsFCont())
						LsPut(hc, b, LsKTextx(), tx)
						LsPut(hc, b, LsKTol(), tl)
						cur = b
						more = 1
					}
				}
				steps += 1
			}
		}
		l += 1
	}
	return 0
}

func LsAnalyze(wd *port.Cells, ln *port.Cells, et *port.Cells, sf *port.Cells, pa *port.Cells, hc *port.Cells, cd *port.Cells, pi *port.Cells, ws *port.Cells) int32 {
	// Find the lines that start an item and mark them (see the module's head). `cd`, `pi`, `ws` are scratch.
	// Answers the number of item lines found. The heading rows of `hc` must be there (`hd-analyze` ran); when
	// they are not nothing is done.
	if LsOpen(hc) == 0 {
		return 0
	}
	var i int32 = 0
	var found int32 = 0
	port.CellsDrop(ws, 0)
	for i < 8 {
		port.CellsPush(ws, 0)
		i += 1
	}
	if lsPages(ln, pi) == 1 {
		lsShapes(ln, sf, pa, pi, hc)
	}
	var nc int32 = lsCollect(wd, ln, et, hc, cd, ws)
	i = 0
	for i < nc {
		var l int32 = lsCget(cd, i, 0)
		var cls int32 = lsCget(cd, i, 8)
		var w int32 = LsFirstWord(wd, ln, l)
		var conf int32 = lsConfirm(cd, nc, i)
		var textx int32 = lsCget(cd, i, 7)
		// a lone candidate needs a hanging continuation under it (a number or a letter, a bullet or a shape)
		if (conf == 0) && (textx > 0) && (cls != 2) {
			if lsHangEvidence(ln, sf, hc, l, textx) == 1 {
				conf = 1
			}
		}
		if conf > 0 {
			var sch int32 = lsPick(lsCget(cd, i, 2), lsCget(cd, i, 4), conf)
			var val int32 = -1
			var bch int32 = -1
			var mlen int32 = lsMlen(wd, et, w, ws)
			if cls == 3 {
				val = lsPick(lsCget(cd, i, 3), lsCget(cd, i, 5), conf)
			} else {
				bch = lsCget(cd, i, 9)
			}
			if cls == 4 {
				var shape int32 = LsGet(hc, l, LsKShape()) - 1
				var sx int32 = evidence.PaGet(pa, shape, evidence.PfX0())
				lsWrapItem(wd, et, w, LsScBullet(), -1, 0, lsShapeChar(pa, shape))
				if sx < evidence.LnGet(ln, l, evidence.LhX0()) {
					evidence.LnSet(ln, l, evidence.LhX0(), sx)
				}
			} else {
				lsWrapItem(wd, et, w, sch, val, mlen, bch)
			}
			LsPut(hc, l, LsKFlags(), LsFItem())
			LsPut(hc, l, LsKTextx(), textx)
			LsPut(hc, l, LsKMarkx(), evidence.LnGet(ln, l, evidence.LhX0()))
			LsPut(hc, l, LsKTol(), LsLineSize(sf, ln, l)/2)
			found += 1
		}
		i += 1
	}
	lsWalk(ln, sf, hc)
	return found
}
